const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// =============================================================\n// MemoFlow Database Schema — Base Configuration\n// =============================================================\n//\n// This file contains the generator and datasource configuration\n// All model files in this folder will be automatically included\n// =============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ==========================================\n// Account Module\n// 账户聚合根\n// ==========================================\n\nmodel Account {\n  id        String    @id // same as CloudAuthUser.id for cloud accounts\n  status    String    @default(\"Active\") // AccountStatus: Active | Closed\n  // profile\n  profile   Json\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  closedAt  DateTime? @map(\"closed_at\")\n\n  // 关联关系\n  cloudUser CloudAuthUser @relation(fields: [id], references: [id], onDelete: Cascade)\n\n  // 关联的业务模块\n  goals                         Goal[]\n  labels                        Label[]\n  goalLabels                    GoalLabel[]\n  taskLabels                    TaskLabel[]\n  routineDefinitions            RoutineDefinition[]\n  routineTemporaryOverrides     RoutineTemporaryOverride[]\n  routineProfiles               RoutineProfile[]\n  routineProfileMemberships     RoutineProfileMembership[]\n  routineProtocolDefinitions    RoutineProtocolDefinition[]\n  routineProtocolSessions       RoutineProtocolSession[]\n  repositories                  Repository[]\n  repositoryExplorers           RepositoryExplorer[]\n  repositoryStatistics          RepositoryStatistic?\n  schedules                     Schedule[]\n  schedulingReconcileOperations SchedulingReconcileOperation[]\n  scheduledInvocations          ScheduledInvocation[]\n  invocationAttempts            InvocationAttempt[]\n  habits                        Habit[]\n  relations                     Relation[]\n  walletAccounts                WalletAccount[]\n  walletTransactions            WalletTransaction[]            @relation(\"AccountWalletTransactions\")\n  activityLedger                ActivityLedger[]\n  taskPlans                     TaskPlan[]\n  taskOccurrences               TaskOccurrence[]\n  userPreferenceRecords         UserPreferenceRecord[]\n  notifications                 Notification[]\n  aiConversations               AiConversation[]\n  aiGenerationTasks             AiGenerationTask[]\n  aiKnowledgeIndexEntries       AiKnowledgeIndexEntry[]\n  aiUsageQuotas                 AiUsageQuota?\n  aiProviderConfigs             AiProviderConfig[]\n  aiProviderOnboardingSessions  AiProviderOnboardingSession[]\n  dashboardConfigs              DashboardConfig?\n\n  // PowerSync: denormalized identity relations\n  taskPlanHistory                        TaskPlanHistory[]                       @relation(\"AccountTaskPlanHistory\")\n  routineOccurrences                     RoutineOccurrence[]                     @relation(\"AccountRoutineOccurrences\")\n  routineInteractions                    RoutineInteraction[]\n  notificationInteractions               NotificationInteraction[]               @relation(\"AccountNotificationInteractions\")\n  notificationDispatchOutboxes           NotificationDispatchOutbox[]            @relation(\"AccountNotificationDispatchOutboxes\")\n  aiMessages                             AiMessage[]                             @relation(\"AccountAiMessages\")\n  folders                                Folder[]                                @relation(\"AccountFolders\")\n  resources                              Resource[]                              @relation(\"AccountResources\")\n  repositoryResources                    RepositoryResource[]                    @relation(\"AccountRepositoryResources\")\n  knowledgeRemoteBindings                KnowledgeRemoteBinding[]\n  knowledgeRepositoryInstallationIntents KnowledgeRepositoryInstallationIntent[]\n  knowledgeWriteRequests                 KnowledgeWriteRequest[]\n\n  @@map(\"accounts\")\n}\n\n// ==========================================\n// Activity Ledger (R6)\n// 全业务事件的可解释活动账本（Dashboard 读模型之源）\n// ==========================================\n\nmodel ActivityLedger {\n  id            String   @id\n  identityId    String   @map(\"identity_id\")\n  actorId       String   @map(\"actor_id\")\n  subjectType   String   @map(\"subject_type\") /// goal | task (Routine projection joins in Phase 5)\n  subjectId     String   @map(\"subject_id\")\n  action        String   @map(\"action\") /// created | completed | updated | response | executed | ...\n  title         String? /// 归档标题快照（跨 DST/归档实体仍显示准确标题）\n  correlationId String?  @map(\"correlation_id\")\n  beforeSummary String?  @map(\"before_summary\")\n  afterSummary  String?  @map(\"after_summary\")\n  sourceEvent   String   @map(\"source_event\")\n  occurredAt    DateTime @map(\"occurred_at\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId, occurredAt])\n  @@index([identityId, subjectType, subjectId])\n  @@map(\"activity_ledger\")\n}\n\n// ==========================================\n// AI Module\n// AI 对话、消息、生成任务、配额、Provider 配置\n// ==========================================\n\nmodel AiConversation {\n  id            String    @id\n  identityId    String    @map(\"identity_id\")\n  name          String\n  status        String // ACTIVE, CLOSED, ARCHIVED\n  messageCount  Int       @default(0) @map(\"message_count\")\n  lastMessageAt DateTime? @map(\"last_message_at\")\n  version       Int       @default(1)\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt     DateTime? @map(\"deleted_at\")\n\n  account  Account     @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  messages AiMessage[]\n\n  @@index([identityId])\n  @@index([status])\n  @@index([createdAt])\n  @@index([lastMessageAt])\n  @@map(\"ai_conversations\")\n}\n\nmodel AiMessage {\n  id             String   @id\n  identityId     String   @map(\"identity_id\")\n  conversationId String   @map(\"conversation_id\")\n  role           String // USER, ASSISTANT, SYSTEM\n  content        String   @db.Text\n  tokenUsage     String?  @map(\"token_usage\") // JSON\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  identity     Account        @relation(\"AccountAiMessages\", fields: [identityId], references: [id])\n  conversation AiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([conversationId])\n  @@index([createdAt])\n  @@map(\"ai_messages\")\n}\n\nmodel AiGenerationTask {\n  id               String    @id\n  identityId       String    @map(\"identity_id\")\n  taskType         String    @map(\"task_type\") // GOAL_KEY_RESULTS, TASK_TEMPLATES, etc.\n  status           String // PENDING, PROCESSING, COMPLETED, FAILED\n  conversationId   String?   @map(\"conversation_id\")\n  runId            String?   @map(\"run_id\")\n  requestId        String?   @map(\"request_id\")\n  traceId          String?   @map(\"trace_id\")\n  providerId       String?   @map(\"provider_id\")\n  model            String?\n  estimatedCostUsd Float?    @map(\"estimated_cost_usd\")\n  input            String    @db.Text // JSON string\n  result           String?   @db.Text // JSON string\n  error            String?   @db.Text\n  retryCount       Int       @default(0) @map(\"retry_count\")\n  tokenUsage       String?   @map(\"token_usage\") // JSON\n  processingMs     Int?      @map(\"processing_ms\")\n  version          Int       @default(1)\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  completedAt      DateTime? @map(\"completed_at\")\n  deletedAt        DateTime? @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([taskType])\n  @@index([status])\n  @@index([createdAt])\n  @@index([identityId, conversationId, createdAt])\n  @@index([identityId, runId, createdAt])\n  @@map(\"ai_generation_tasks\")\n}\n\nmodel AiUsageQuota {\n  id           String    @id\n  identityId   String    @unique @map(\"identity_id\")\n  quotaLimit   Int       @default(50) @map(\"quota_limit\")\n  currentUsage Int       @default(0) @map(\"current_usage\")\n  resetPeriod  String    @default(\"DAILY\") @map(\"reset_period\") // DAILY, WEEKLY, MONTHLY\n  lastResetAt  DateTime  @default(now()) @map(\"last_reset_at\")\n  nextResetAt  DateTime  @map(\"next_reset_at\")\n  version      Int       @default(1)\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([nextResetAt])\n  @@map(\"ai_usage_quotas\")\n}\n\nmodel AiProviderConfig {\n  id              String    @id\n  identityId      String    @map(\"identity_id\")\n  name            String // 配置名称\n  providerType    String    @map(\"provider_type\") // OPENAI, QINIU, ANTHROPIC, CUSTOM_OPENAI_COMPATIBLE\n  baseUrl         String    @map(\"base_url\") // API 基础地址\n  apiKeyEncrypted String    @map(\"api_key_encrypted\") // AES-256-GCM 加密的 API Key\n  defaultModel    String?   @map(\"default_model\")\n  availableModels String    @default(\"[]\") @map(\"available_models\") // 可用模型列表 JSON\n  isActive        Boolean   @default(true) @map(\"is_active\")\n  isDefault       Boolean   @default(false) @map(\"is_default\")\n  priority        Int       @default(100) // 优先级\n  version         Int       @default(1)\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt       DateTime? @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, name])\n  @@index([identityId])\n  @@index([isDefault])\n  @@index([isActive])\n  @@index([priority])\n  @@map(\"ai_provider_configs\")\n}\n\nmodel AiProviderOnboardingSession {\n  id                  String    @id\n  identityId          String    @map(\"identity_id\")\n  catalogId           String    @map(\"catalog_id\")\n  baseUrl             String    @map(\"base_url\")\n  targetProviderId    String?   @map(\"target_provider_id\")\n  credentialEncrypted String    @map(\"credential_encrypted\")\n  credentialStatus    String    @map(\"credential_status\")\n  discoveryStatus     String    @map(\"discovery_status\")\n  modelsJson          String    @default(\"[]\") @map(\"models_json\")\n  verifiedModelIds    String    @default(\"[]\") @map(\"verified_model_ids\")\n  expiresAt           DateTime  @map(\"expires_at\")\n  consumedAt          DateTime? @map(\"consumed_at\")\n  createdAt           DateTime  @default(now()) @map(\"created_at\")\n  updatedAt           DateTime  @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId, expiresAt])\n  @@index([identityId, targetProviderId, expiresAt])\n  @@index([expiresAt])\n  @@map(\"ai_provider_onboarding_sessions\")\n}\n\nmodel KnowledgeGenerationTask {\n  id                   String    @id\n  identityId           String    @map(\"identity_id\")\n  topic                String\n  resourceCount        Int       @default(5) @map(\"resource_count\")\n  targetAudience       String?   @map(\"target_audience\")\n  folderPath           String    @map(\"folder_path\")\n  status               String // PENDING, GENERATING, COMPLETED, FAILED\n  progress             Int       @default(0) // 0-100\n  generatedResourceIds String[]  @map(\"generated_resource_ids\")\n  error                String?   @db.Text\n  createdAt            DateTime  @default(now()) @map(\"created_at\")\n  completedAt          DateTime? @map(\"completed_at\")\n\n  @@index([identityId])\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"knowledge_generation_tasks\")\n}\n\nmodel AiKnowledgeIndexEntry {\n  id              String                     @id\n  identityId      String                     @map(\"identity_id\")\n  repositoryId    String                     @map(\"repository_id\")\n  resourceId      String                     @unique @map(\"resource_id\")\n  resourcePath    String                     @map(\"resource_path\")\n  title           String?\n  mimeType        String                     @map(\"mime_type\")\n  contentHash     String                     @map(\"content_hash\")\n  status          String\n  summary         String?                    @db.Text\n  keywords        Json                       @default(\"[]\")\n  embedding       Json?\n  retrievalVector Unsupported(\"vector(48)\")? @map(\"retrieval_vector\")\n  chunks          Json?\n  metadata        Json                       @default(\"{}\")\n  error           String?                    @db.Text\n  indexedAt       DateTime                   @map(\"indexed_at\")\n  lastRequestedAt DateTime?                  @map(\"last_requested_at\")\n  createdAt       DateTime                   @default(now()) @map(\"created_at\")\n  updatedAt       DateTime                   @updatedAt @map(\"updated_at\")\n  deletedAt       DateTime?                  @map(\"deleted_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([repositoryId])\n  @@index([status])\n  @@index([lastRequestedAt])\n  @@map(\"ai_knowledge_index_entries\")\n}\n\nmodel DashboardConfig {\n  id           Int      @id @default(autoincrement())\n  identityId   String   @unique @map(\"identity_id\")\n  widgetConfig Json     @map(\"widget_config\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"dashboard_configs\")\n}\n\n// Better Auth cloud identity source.\n// Explicit model names avoid confusing provider accounts with MemoFlow Account.\n\nmodel CloudAuthUser {\n  id            String    @id @default(uuid())\n  name          String\n  email         String    @unique\n  emailVerified Boolean   @default(false) @map(\"email_verified\")\n  image         String?\n  disabledAt    DateTime? @map(\"disabled_at\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n\n  sessions         CloudAuthSession[]\n  providerAccounts CloudAuthProviderAccount[]\n  deviceCodes      CloudAuthDeviceCode[]\n  account          Account?\n\n  @@map(\"cloud_auth_users\")\n}\n\nmodel CloudAuthSession {\n  id        String   @id @default(uuid())\n  userId    String   @map(\"user_id\")\n  token     String   @unique\n  expiresAt DateTime @map(\"expires_at\")\n  ipAddress String?  @map(\"ip_address\")\n  userAgent String?  @map(\"user_agent\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  user CloudAuthUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([expiresAt])\n  @@map(\"cloud_auth_sessions\")\n}\n\nmodel CloudAuthProviderAccount {\n  id                    String    @id @default(uuid())\n  userId                String    @map(\"user_id\")\n  accountId             String    @map(\"account_id\")\n  providerId            String    @map(\"provider_id\")\n  accessToken           String?   @map(\"access_token\")\n  refreshToken          String?   @map(\"refresh_token\")\n  idToken               String?   @map(\"id_token\")\n  accessTokenExpiresAt  DateTime? @map(\"access_token_expires_at\")\n  refreshTokenExpiresAt DateTime? @map(\"refresh_token_expires_at\")\n  scope                 String?\n  password              String?\n  createdAt             DateTime  @default(now()) @map(\"created_at\")\n  updatedAt             DateTime  @updatedAt @map(\"updated_at\")\n\n  user CloudAuthUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([providerId, accountId])\n  @@index([userId])\n  @@map(\"cloud_auth_provider_accounts\")\n}\n\nmodel CloudAuthVerification {\n  id         String   @id @default(uuid())\n  identifier String\n  value      String\n  expiresAt  DateTime @map(\"expires_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([identifier])\n  @@map(\"cloud_auth_verifications\")\n}\n\nmodel CloudAuthDeviceCode {\n  id              String    @id @default(uuid())\n  deviceCode      String    @unique @map(\"device_code\")\n  userCode        String    @unique @map(\"user_code\")\n  userId          String?   @map(\"user_id\")\n  expiresAt       DateTime  @map(\"expires_at\")\n  status          String\n  lastPolledAt    DateTime? @map(\"last_polled_at\")\n  pollingInterval Int?      @map(\"polling_interval\")\n  clientId        String?   @map(\"client_id\")\n  scope           String?\n\n  user CloudAuthUser? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([expiresAt])\n  @@index([userId])\n  @@map(\"cloud_auth_device_codes\")\n}\n\n// ==========================================\n// Goal Module — Core vNext\n// Goal = Direction + Measurement\n// ==========================================\n\nmodel Goal {\n  id             String    @id\n  identityId     String    @map(\"identity_id\")\n  name           String\n  summary        String?\n  status         String    @default(\"Planned\")\n  startDate      String?   @map(\"start_date\")\n  targetKind     String?   @map(\"target_kind\")\n  targetEndDate  String?   @map(\"target_end_date\")\n  completedAt    DateTime? @map(\"completed_at\")\n  archivedAt     DateTime? @map(\"archived_at\")\n  sortOrder      Int       @default(0) @map(\"sort_order\")\n  reminderConfig String?   @map(\"reminder_config\")\n  version        Int       @default(1)\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt      DateTime? @map(\"deleted_at\")\n\n  account                  Account                   @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  keyResults               KeyResult[]               @relation(\"GoalKeyResults\")\n  reviews                  GoalReview[]\n  keyResultWeightSnapshots KeyResultWeightSnapshot[]\n  labelLinks               GoalLabel[]\n\n  @@unique([id, identityId])\n  @@index([identityId, status])\n  @@index([identityId, targetEndDate])\n  @@index([targetEndDate])\n  @@index([deletedAt])\n  @@map(\"goals\")\n}\n\nmodel KeyResult {\n  id                String   @id\n  identityId        String   @map(\"identity_id\")\n  goalId            String   @map(\"goal_id\")\n  title             String\n  description       String?\n  aggregationMethod String   @map(\"aggregation_method\")\n  initialValue      Float    @default(0) @map(\"initial_value\")\n  trackingBaseValue Float    @default(0) @map(\"tracking_base_value\")\n  targetValue       Float    @map(\"target_value\")\n  currentValue      Float    @default(0) @map(\"current_value\")\n  targetKind        String?  @map(\"target_kind\")\n  targetEndDate     String?  @map(\"target_end_date\")\n  unit              String?\n  weight            Int      @default(1)\n  order             Int      @default(0)\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n  updatedAt         DateTime @updatedAt @map(\"updated_at\")\n\n  goal                     Goal                      @relation(\"GoalKeyResults\", fields: [goalId, identityId], references: [id, identityId], onDelete: Cascade)\n  linkedTaskPlans          TaskPlan[]                @relation(\"KeyResultTaskPlans\")\n  records                  GoalRecord[]\n  keyResultWeightSnapshots KeyResultWeightSnapshot[]\n\n  @@unique([id, identityId])\n  @@unique([id, goalId, identityId])\n  @@index([identityId])\n  @@index([goalId])\n  @@index([goalId, order])\n  @@map(\"key_results\")\n}\n\nmodel GoalRecord {\n  id          String   @id\n  identityId  String   @map(\"identity_id\")\n  keyResultId String   @map(\"key_result_id\")\n  value       Float\n  note        String?\n  sourceType  String?  @map(\"source_type\")\n  sourceId    String?  @map(\"source_id\")\n  recordedAt  DateTime @map(\"recorded_at\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  keyResult KeyResult @relation(fields: [keyResultId, identityId], references: [id, identityId], onDelete: Cascade)\n\n  @@unique([identityId, sourceType, sourceId])\n  @@index([identityId])\n  @@index([keyResultId, recordedAt])\n  @@index([recordedAt])\n  @@map(\"goal_records\")\n}\n\nmodel GoalReview {\n  id            String   @id\n  identityId    String   @map(\"identity_id\")\n  goalId        String   @map(\"goal_id\")\n  reflection    String\n  challenges    String?\n  adjustments   String?\n  systemContext String   @map(\"system_context\")\n  reviewedAt    DateTime @map(\"reviewed_at\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  goal Goal @relation(fields: [goalId, identityId], references: [id, identityId], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([goalId, reviewedAt])\n  @@map(\"goal_reviews\")\n}\n\nmodel KeyResultWeightSnapshot {\n  id           String   @id\n  identityId   String   @map(\"identity_id\")\n  goalId       String   @map(\"goal_id\")\n  keyResultId  String   @map(\"key_result_id\")\n  oldWeight    Int      @map(\"old_weight\")\n  newWeight    Int      @map(\"new_weight\")\n  weightDelta  Int      @map(\"weight_delta\")\n  snapshotTime DateTime @map(\"snapshot_time\")\n  trigger      String\n  reason       String?\n  operatorId   String   @map(\"operator_id\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  goal      Goal      @relation(fields: [goalId, identityId], references: [id, identityId], onDelete: Cascade)\n  keyResult KeyResult @relation(fields: [keyResultId, goalId, identityId], references: [id, goalId, identityId], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([goalId, snapshotTime])\n  @@index([keyResultId, snapshotTime])\n  @@index([snapshotTime])\n  @@map(\"key_result_weight_snapshots\")\n}\n\n// ==========================================\n// Governance Module\n// 规则管理、规则修订记录\n// ==========================================\n\n// ==========================================\n// 1. 规则聚合根表 (Rule)\n// ==========================================\nmodel Rule {\n  id          String @id @default(uuid())\n  code        String @unique // 规则编码，格式：PREFIX-NUMBER (e.g., DDD-001)\n  title       String // 规则标题\n  description String // 规则描述\n\n  severity String @default(\"Recommended\") // Mandatory | Recommended\n  status   String @default(\"Draft\") // Draft | Active | Deprecated\n\n  deprecationReason     String? @map(\"deprecation_reason\")\n  replacementRuleId     String? @map(\"replacement_rule_id\")\n  liveReferenceLocation String? @map(\"live_reference_location\")\n\n  // JSON fields\n  tags         String // JSON array of tag strings\n  goodExamples String @map(\"good_examples\") // JSON array of code snippets\n  badExamples  String @map(\"bad_examples\") // JSON array of code snippets\n\n  authorId String @map(\"author_id\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  // 关联\n  revisions RuleRevision[]\n\n  @@map(\"rules\")\n}\n\n// ==========================================\n// 2. 规则修订记录表 (RuleRevision)\n// ==========================================\nmodel RuleRevision {\n  id             String @id @default(uuid())\n  ruleId         String @map(\"rule_id\")\n  revisionNumber Int    @map(\"revision_number\")\n\n  authorId       String  @map(\"author_id\")\n  changedFields  String  @map(\"changed_fields\") // JSON array\n  previousValues String? @map(\"previous_values\") // JSON object\n  newValues      String? @map(\"new_values\") // JSON object\n  changeType     String  @map(\"change_type\") // Created | Updated | Deprecated | Reactivated\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  // 关联\n  rule Rule @relation(fields: [ruleId], references: [id], onDelete: Cascade)\n\n  @@unique([ruleId, revisionNumber])\n  @@map(\"rule_revisions\")\n}\n\n// ==========================================\n// Habit Module (R4)\n// 习惯、习惯发生、打卡与连续天数投影\n// ==========================================\n\nmodel Habit {\n  id          String    @id\n  identityId  String    @map(\"identity_id\")\n  name        String\n  description String?\n  frequency   String    @default(\"daily\") /// daily | weekly\n  goalId      String?   @map(\"goal_id\") /// 关联目标（贡献策略使用）\n  status      String    @default(\"Active\") /// Active | Archived\n  startDate   DateTime? @map(\"start_date\")\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  occurrences HabitOccurrence[]\n  streak      HabitStreakProjection?\n\n  @@index([identityId])\n  @@map(\"habits\")\n}\n\nmodel HabitOccurrence {\n  id             String   @id\n  habitId        String   @map(\"habit_id\")\n  occurrenceDate DateTime @map(\"occurrence_date\") /// 本地日 00:00\n  status         String   @default(\"Pending\") /// Pending | Completed | Skipped\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  habit    Habit          @relation(fields: [habitId], references: [id], onDelete: Cascade)\n  checkIns HabitCheckIn[]\n\n  @@unique([habitId, occurrenceDate])\n  @@index([habitId, status])\n  @@map(\"habit_occurrences\")\n}\n\nmodel HabitCheckIn {\n  id           String   @id\n  occurrenceId String   @map(\"occurrence_id\")\n  checkedAt    DateTime @map(\"checked_at\")\n  note         String?\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  occurrence HabitOccurrence @relation(fields: [occurrenceId], references: [id], onDelete: Cascade)\n\n  @@index([occurrenceId])\n  @@map(\"habit_check_ins\")\n}\n\nmodel HabitStreakProjection {\n  id              String    @id\n  habitId         String    @unique @map(\"habit_id\")\n  currentStreak   Int       @map(\"current_streak\")\n  longestStreak   Int       @map(\"longest_streak\")\n  lastCheckInDate DateTime? @map(\"last_check_in_date\")\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n\n  habit Habit @relation(fields: [habitId], references: [id], onDelete: Cascade)\n\n  @@map(\"habit_streak_projections\")\n}\n\n// ==========================================\n// Shared Labels (ADR-054)\n// User-owned classification shared by Goal and Task.\n// ==========================================\n\nmodel Label {\n  id             String   @id\n  identityId     String   @map(\"identity_id\")\n  name           String\n  normalizedName String   @map(\"normalized_name\")\n  color          String?\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  account   Account     @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  goalLinks GoalLabel[]\n  taskLinks TaskLabel[]\n\n  @@unique([id, identityId])\n  @@unique([identityId, normalizedName])\n  @@index([identityId, name])\n  @@map(\"labels\")\n}\n\nmodel GoalLabel {\n  identityId String @map(\"identity_id\")\n  goalId     String @map(\"goal_id\")\n  labelId    String @map(\"label_id\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  goal    Goal    @relation(fields: [goalId, identityId], references: [id, identityId], onDelete: Cascade)\n  label   Label   @relation(fields: [labelId, identityId], references: [id, identityId], onDelete: Cascade)\n\n  @@id([identityId, goalId, labelId])\n  @@index([identityId, labelId, goalId])\n  @@map(\"goal_labels\")\n}\n\nmodel TaskLabel {\n  identityId String @map(\"identity_id\")\n  taskPlanId String @map(\"task_plan_id\")\n  labelId    String @map(\"label_id\")\n\n  account  Account  @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  taskPlan TaskPlan @relation(fields: [taskPlanId, identityId], references: [id, identityId], onDelete: Cascade)\n  label    Label    @relation(fields: [labelId, identityId], references: [id, identityId], onDelete: Cascade)\n\n  @@id([identityId, taskPlanId, labelId])\n  @@index([identityId, labelId, taskPlanId])\n  @@map(\"task_labels\")\n}\n\n// ==========================================\n// Notification Module\n// 通知 Fact、Inbox、交互与投递执行\n// ==========================================\n\nmodel Notification {\n  id                String    @id\n  identityId        String    @map(\"identity_id\")\n  type              String\n  category          String\n  workflowKey       String    @map(\"workflow_key\")\n  topic             String\n  idempotencyKey    String    @map(\"idempotency_key\")\n  title             String\n  content           String\n  importance        String\n  urgency           String\n  relatedEntityType String?   @map(\"related_entity_type\")\n  relatedEntityId   String?   @map(\"related_entity_id\")\n  metadata          String?\n  actions           String?\n  navigationIntent  String?   @map(\"navigation_intent\")\n  correlationId     String?   @map(\"correlation_id\")\n  causationId       String?   @map(\"causation_id\")\n  readAt            DateTime? @map(\"read_at\")\n  expiresAt         DateTime? @map(\"expires_at\")\n  version           Int       @default(1)\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt         DateTime? @map(\"deleted_at\")\n  archivedAt        DateTime? @map(\"archived_at\")\n  isRead            Boolean   @default(false) @map(\"is_read\")\n\n  interactions      NotificationInteraction[]\n  dispatchOutboxes  NotificationDispatchOutbox[]\n  deliveryDecisions NotificationDeliveryDecisionRecord[]\n  account           Account                              @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, idempotencyKey])\n  @@index([identityId, workflowKey])\n  @@index([identityId, archivedAt, createdAt])\n  @@map(\"notifications\")\n}\n\nmodel NotificationInteraction {\n  id               String   @id\n  idempotencyKey   String   @unique @map(\"idempotency_key\")\n  identityId       String   @map(\"identity_id\")\n  notificationId   String   @map(\"notification_id\")\n  actionKey        String   @map(\"action_key\")\n  actionKind       String   @map(\"action_kind\")\n  occurredAt       DateTime @map(\"occurred_at\")\n  commandReceiptId String?  @map(\"command_receipt_id\")\n  outcome          String\n  correlationId    String?  @map(\"correlation_id\")\n  causationId      String?  @map(\"causation_id\")\n\n  identity     Account      @relation(\"AccountNotificationInteractions\", fields: [identityId], references: [id], onDelete: Cascade)\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n\n  @@index([identityId, occurredAt])\n  @@index([notificationId, occurredAt])\n  @@map(\"notification_interactions\")\n}\n\nmodel NotificationDeliveryDecisionRecord {\n  id               String    @id\n  identityId       String    @map(\"identity_id\")\n  notificationId   String    @map(\"notification_id\")\n  channel          String\n  outcome          String\n  reason           String\n  preferenceSource String?   @map(\"preference_source\")\n  retryAt          DateTime? @map(\"retry_at\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n\n  @@unique([notificationId, channel])\n  @@index([identityId])\n  @@map(\"notification_delivery_decisions\")\n}\n\nmodel NotificationPreference {\n  id                String    @id\n  identityId        String    @unique @map(\"identity_id\")\n  globalChannels    String    @default(\"{}\") @map(\"global_channels\")\n  workflowOverrides String    @default(\"{}\") @map(\"workflow_overrides\")\n  quietHours        String?   @map(\"quiet_hours\")\n  version           Int       @default(1)\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt         DateTime? @map(\"deleted_at\")\n\n  @@index([identityId])\n  @@map(\"notification_preferences\")\n}\n\n/// NotificationDispatchOutbox 投递意图/Outbox（W2: LeaseClaim 与 durable receipt）\nmodel NotificationDispatchOutbox {\n  id                  String    @id\n  identityId          String    @map(\"identity_id\")\n  notificationId      String    @map(\"notification_id\")\n  source              String    @default(\"notification\")\n  occurrenceKey       String    @map(\"occurrence_key\")\n  channel             String\n  payloadJson         String    @map(\"payload_json\")\n  idempotencyKey      String    @unique @map(\"idempotency_key\")\n  status              String\n  attempt             Int       @default(0)\n  ownerToken          String?   @map(\"owner_token\")\n  claimId             String?   @map(\"claim_id\")\n  fencingToken        Int       @default(0) @map(\"fencing_token\")\n  leaseExpiresAt      DateTime? @map(\"lease_expires_at\")\n  lastHeartbeatAt     DateTime? @map(\"last_heartbeat_at\")\n  heartbeatIntervalMs Int?      @map(\"heartbeat_interval_ms\")\n  lastError           String?   @map(\"last_error\")\n  nextRetryAt         DateTime? @map(\"next_retry_at\")\n  deadLetterAt        DateTime? @map(\"dead_letter_at\")\n  correlationId       String?   @map(\"correlation_id\")\n  causationId         String?   @map(\"causation_id\")\n  attemptsHistoryJson String?   @map(\"attempts_history_json\")\n  createdAt           DateTime  @default(now()) @map(\"created_at\")\n  updatedAt           DateTime  @updatedAt @map(\"updated_at\")\n  finishedAt          DateTime? @map(\"finished_at\")\n\n  notification Notification @relation(fields: [notificationId], references: [id], onDelete: Cascade)\n  account      Account      @relation(\"AccountNotificationDispatchOutboxes\", fields: [identityId], references: [id])\n\n  @@index([identityId])\n  @@index([status])\n  @@index([leaseExpiresAt])\n  @@map(\"notification_dispatch_outbox\")\n}\n\n// ==========================================\n// Relation Module (R5)\n// 跨模块 SubjectRef 关系：Note/Goal/Task/Habit/Wallet 双向连接\n// ==========================================\n\nmodel Relation {\n  id           String   @id\n  identityId   String   @map(\"identity_id\")\n  subjectType  String   @map(\"subject_type\") /// note | goal | task | habit | wallet\n  subjectId    String   @map(\"subject_id\")\n  relationType String   @map(\"relation_type\") /// references | related | depends_on | contributes_to\n  objectType   String   @map(\"object_type\")\n  objectId     String   @map(\"object_id\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, subjectType, subjectId, relationType, objectType, objectId])\n  @@index([identityId, objectType, objectId]) /// 反向查询\n  @@map(\"relations\")\n}\n\n// ==========================================\n// Reliable Messaging (R1-1)\n// 通用 outbox / inbox receipt / projection cursor\n// 提供跨模块副作用的 durable 边界与崩溃恢复游标\n// ==========================================\n\n/// Outbox 消息：跨模块写入与投递意图的 durable 队列。\n/// AggregateRepositoryBase 发布事件失败时落入此表，由 dispatcher 重试投递。\nmodel OutboxMessage {\n  id              String    @id\n  identityId      String?   @map(\"identity_id\")\n  messageType     String    @map(\"message_type\")\n  schemaVersion   Int       @default(1) @map(\"schema_version\")\n  correlationId   String    @map(\"correlation_id\")\n  causationId     String?   @map(\"causation_id\")\n  payloadJson     String    @map(\"payload_json\")\n  idempotencyKey  String?   @unique @map(\"idempotency_key\")\n  status          String    @default(\"pending\")\n  attempts        Int       @default(0)\n  availableAt     DateTime  @default(now()) @map(\"available_at\")\n  lastError       String?   @map(\"last_error\")\n  dispatchedAt    DateTime? @map(\"dispatched_at\")\n  createdAt       DateTime  @default(now()) @map(\"created_at\")\n  ownerToken      String?\n  claimId         String?\n  fencingToken    Int?\n  leaseExpiresAt  DateTime? @map(\"lease_expires_at\")\n  lastHeartbeatAt DateTime? @map(\"last_heartbeat_at\")\n\n  @@index([status, availableAt])\n  @@index([correlationId])\n  @@index([messageType])\n  @@map(\"reliable_outbox_messages\")\n}\n\n/// Inbox 回执：同一消息对同一消费者只允许一次成功处理（幂等去重）。\nmodel InboxReceipt {\n  id          String\n  consumer    String\n  outcome     String\n  error       String?\n  processedAt DateTime @default(now()) @map(\"processed_at\")\n\n  @@id([id, consumer])\n  @@index([consumer, outcome])\n  @@map(\"reliable_inbox_receipts\")\n}\n\n/// Projection 游标：启动 reconcile 与增量重放的断点。\nmodel ProjectionCursor {\n  projector       String\n  sourceName      String    @map(\"source_name\")\n  lastProcessedId String?   @map(\"last_processed_id\")\n  lastProcessedAt DateTime? @map(\"last_processed_at\")\n  version         Int       @default(0)\n  updatedAt       DateTime  @updatedAt @map(\"updated_at\")\n\n  @@id([projector, sourceName])\n  @@map(\"reliable_projection_cursors\")\n}\n\n/// 闭户操作表：记录账户注销 saga 的状态、幂等键与恢复点。\nmodel AccountClosureOperation {\n  id               String    @id @default(uuid())\n  identityId       String    @map(\"identity_id\")\n  idempotencyKey   String    @map(\"idempotency_key\")\n  phase            String\n  status           String\n  attempts         Int       @default(0)\n  version          Int       @default(1)\n  ownerToken       String?   @map(\"owner_token\")\n  leaseExpiresAt   DateTime? @map(\"lease_expires_at\")\n  lastHeartbeatAt  DateTime? @map(\"last_heartbeat_at\")\n  nextRetryAt      DateTime? @map(\"next_retry_at\")\n  deadLetterAt     DateTime? @map(\"dead_letter_at\")\n  eventId          String?   @map(\"event_id\")\n  reason           String?\n  revokedSessions  Int       @default(0) @map(\"revoked_sessions\")\n  piiCleanupStatus String?   @map(\"pii_cleanup_status\")\n  piiReason        String?   @map(\"pii_reason\")\n  lastErrorCode    String?   @map(\"last_error_code\")\n  lastError        String?   @map(\"last_error\")\n  receiptJson      String?   @map(\"receipt_json\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  finishedAt       DateTime? @map(\"finished_at\")\n\n  @@unique([identityId, idempotencyKey])\n  @@index([identityId])\n  @@index([identityId, phase])\n  @@map(\"reliable_account_closure_operations\")\n}\n\n/// 运维审计日志 (W7)：记录谁何时对哪个 operation 做了什么（query / replay）。\n/// 跨模块共享：Notification / Schedule rebuild / Account closure / Knowledge projection\n/// 的最小权限查询与 replay 操作都必须写审计记录，禁止静默操作。\nmodel OperationAuditLog {\n  id              String   @id @default(uuid())\n  actorIdentityId String   @map(\"actor_identity_id\")\n  source          String\n  operationId     String   @map(\"operation_id\")\n  action          String\n  details         String?\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n\n  @@index([actorIdentityId, createdAt])\n  @@index([source, operationId])\n  @@index([createdAt])\n  @@map(\"reliable_operation_audit_logs\")\n}\n\n// ==========================================\n// Routine Coach vNext — canonical domain truth\n// ==========================================\n\nmodel RoutineDefinition {\n  id          String   @id\n  identityId  String   @map(\"identity_id\")\n  name        String\n  description String?\n  enabled     Boolean  @default(true)\n  triggerJson String?  @map(\"trigger_json\")\n  version     Int      @default(1)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  account           Account                    @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  memberships       RoutineProfileMembership[]\n  occurrences       RoutineOccurrence[]\n  interactions      RoutineInteraction[]\n  temporaryOverride RoutineTemporaryOverride?\n\n  @@unique([identityId, id])\n  @@index([identityId, enabled])\n  @@map(\"routine_definitions\")\n}\n\nmodel RoutineProfile {\n  id          String   @id\n  identityId  String   @map(\"identity_id\")\n  name        String\n  description String?\n  enabled     Boolean  @default(true)\n  version     Int      @default(1)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  account     Account                    @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  memberships RoutineProfileMembership[]\n\n  @@unique([identityId, id])\n  @@index([identityId, enabled])\n  @@map(\"routine_profiles\")\n}\n\nmodel RoutineProfileMembership {\n  identityId String   @map(\"identity_id\")\n  profileId  String   @map(\"profile_id\")\n  routineId  String   @map(\"routine_id\")\n  enabled    Boolean  @default(true)\n  version    Int      @default(1)\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  account Account           @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  profile RoutineProfile    @relation(fields: [profileId, identityId], references: [id, identityId], onDelete: Cascade)\n  routine RoutineDefinition @relation(fields: [routineId, identityId], references: [id, identityId], onDelete: Cascade)\n\n  @@id([identityId, profileId, routineId])\n  @@index([identityId, routineId])\n  @@index([identityId, profileId])\n  @@map(\"routine_profile_memberships\")\n}\n\nmodel RoutineProtocolDefinition {\n  id             String   @id\n  identityId     String   @map(\"identity_id\")\n  name           String\n  definitionJson String   @map(\"definition_json\")\n  version        Int      @default(1)\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  account  Account                  @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  sessions RoutineProtocolSession[]\n\n  @@unique([identityId, id])\n  @@index([identityId, name])\n  @@map(\"routine_protocol_definitions\")\n}\n\nmodel RoutineProtocolSession {\n  id                String    @id\n  identityId        String    @map(\"identity_id\")\n  protocolId        String    @map(\"protocol_id\")\n  protocolVersion   Int       @map(\"protocol_version\")\n  status            String\n  snapshotJson      String    @map(\"snapshot_json\")\n  terminationReason String?   @map(\"termination_reason\")\n  endedAt           DateTime? @map(\"ended_at\")\n  version           Int       @default(1)\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n\n  account  Account                   @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  protocol RoutineProtocolDefinition @relation(fields: [protocolId, identityId], references: [id, identityId], onDelete: Restrict)\n\n  @@index([identityId, status])\n  @@index([identityId, protocolId, createdAt])\n  @@map(\"routine_protocol_sessions\")\n}\n\n/// RoutineOccurrence durable occurrence fence for the ROUTINE-3401 wall-clock lane.\n/// Uses the protected Routine lease-claim/fencing contract (ADR-077)\n/// keyed by the canonical occurrenceKey so crash/retry replay is idempotent.\nmodel RoutineOccurrence {\n  id               String    @id\n  identityId       String    @map(\"identity_id\")\n  routineId        String    @map(\"routine_id\")\n  source           String    @default(\"routine\")\n  occurrenceKey    String    @map(\"occurrence_key\")\n  scheduledFor     DateTime? @map(\"scheduled_for\")\n  sourceRevision   String?   @map(\"source_revision\")\n  idempotencyKey   String    @unique @map(\"idempotency_key\")\n  /// Infrastructure execution status retained during the ADR-077 reliability cutover.\n  status           String\n  /// Routine-owned business truth. Scheduler success must not imply satisfaction.\n  triggerKind      String    @default(\"WallClock\") @map(\"trigger_kind\")\n  becameDueAt      DateTime  @default(now()) @map(\"became_due_at\")\n  resolutionState  String    @default(\"Open\") @map(\"resolution_state\")\n  resolvedAt       DateTime? @map(\"resolved_at\")\n  resolutionKind   String?   @map(\"resolution_kind\")\n  resolutionReason String?   @map(\"resolution_reason\")\n  attempt          Int       @default(0)\n  ownerToken       String?   @map(\"owner_token\")\n  claimId          String?   @map(\"claim_id\")\n  fencingToken     Int       @default(0) @map(\"fencing_token\")\n  leaseExpiresAt   DateTime? @map(\"lease_expires_at\")\n  lastError        String?   @map(\"last_error\")\n  nextRetryAt      DateTime? @map(\"next_retry_at\")\n  deadLetterAt     DateTime? @map(\"dead_letter_at\")\n  correlationId    String?   @map(\"correlation_id\")\n  causationId      String?   @map(\"causation_id\")\n  historyJson      String?   @map(\"history_json\")\n  nextOccurrenceAt DateTime? @map(\"next_occurrence_at\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  finishedAt       DateTime? @map(\"finished_at\")\n\n  routine      RoutineDefinition    @relation(fields: [routineId, identityId], references: [id, identityId], onDelete: Cascade)\n  account      Account              @relation(\"AccountRoutineOccurrences\", fields: [identityId], references: [id])\n  interactions RoutineInteraction[]\n\n  @@unique([identityId, routineId, occurrenceKey])\n  @@index([identityId])\n  @@index([status])\n  @@index([leaseExpiresAt])\n  @@map(\"routine_occurrences\")\n}\n\n/// ROUTINE-3401 durable snooze/suppress state for the routine wall-clock lane.\n/// Temporary override is runtime state kept separate from long-lived trigger\n/// config so a snooze never rewrites `trigger_json` (ADR-059 §6). One row per\n/// routine; the decoded payload uses the W2 trigger-parity codec.\nmodel RoutineInteraction {\n  id                String   @id\n  idempotencyKey    String   @unique @map(\"idempotency_key\")\n  identityId        String   @map(\"identity_id\")\n  routineId         String   @map(\"routine_id\")\n  occurrenceKey     String   @map(\"occurrence_key\")\n  action            String\n  actedAt           DateTime @map(\"acted_at\")\n  responseLatencyMs Int?     @map(\"response_latency_ms\")\n  snoozeDurationMs  Int?     @map(\"snooze_duration_ms\")\n  metadataJson      String?  @map(\"metadata_json\")\n  createdAt         DateTime @default(now()) @map(\"created_at\")\n\n  account    Account            @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  routine    RoutineDefinition  @relation(fields: [routineId, identityId], references: [id, identityId], onDelete: Cascade)\n  occurrence RoutineOccurrence? @relation(fields: [identityId, routineId, occurrenceKey], references: [identityId, routineId, occurrenceKey], onDelete: Cascade)\n\n  @@index([identityId, routineId, actedAt])\n  @@index([identityId, occurrenceKey])\n  @@map(\"routine_interactions\")\n}\n\nmodel RoutineTemporaryOverride {\n  identityId   String   @map(\"identity_id\")\n  routineId    String   @map(\"routine_id\")\n  overrideJson String   @map(\"override_json\")\n  version      Int      @default(1)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  routine RoutineDefinition @relation(fields: [routineId, identityId], references: [id, identityId], onDelete: Cascade)\n  account Account           @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@id([identityId, routineId])\n  @@unique([routineId, identityId])\n  @@map(\"routine_temporary_overrides\")\n}\n\n// ==========================================\n// Repository Module\n// 仓库聚合根、资源、文件夹、浏览器、统计\n// ==========================================\n\nmodel Repository {\n  id             String    @id\n  identityId     String    @map(\"identity_id\")\n  name           String\n  type           String\n  path           String\n  description    String?\n  config         Json      @default(\"{}\") // RepositoryConfig JSONB\n  stats          Json      @default(\"{}\") // RepositoryStats JSONB\n  relatedGoals   String?   @map(\"related_goals\")\n  status         String    @default(\"ACTIVE\") // ACTIVE | ARCHIVED | DELETED\n  git            String?\n  syncStatus     String?   @map(\"sync_status\")\n  lastAccessedAt DateTime? @map(\"last_accessed_at\")\n  version        Int       @default(1)\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt      DateTime? @map(\"deleted_at\")\n\n  account             Account              @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  explorers           RepositoryExplorer[]\n  repositoryResources RepositoryResource[]\n  resources           Resource[]\n  folders             Folder[]\n\n  @@unique([identityId, path])\n  @@index([type])\n  @@index([status])\n  @@map(\"repositories\")\n}\n\nmodel Folder {\n  id           String   @id\n  identityId   String   @map(\"identity_id\")\n  repositoryId String   @map(\"repository_id\")\n  parentId     String?  @map(\"parent_id\")\n  name         String\n  path         String // Auto-generated: /parent/name\n  order        Int      @default(0)\n  isExpanded   Boolean  @default(true) @map(\"is_expanded\")\n  metadata     Json     @default(\"{}\") // FolderMetadata JSONB\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  identity   Account    @relation(\"AccountFolders\", fields: [identityId], references: [id])\n  repository Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n  parent     Folder?    @relation(\"FolderHierarchy\", fields: [parentId], references: [id], onDelete: Cascade)\n  children   Folder[]   @relation(\"FolderHierarchy\")\n\n  @@unique([repositoryId, parentId, name])\n  @@index([identityId])\n  @@index([repositoryId])\n  @@index([parentId])\n  @@index([path])\n  @@map(\"folders\")\n}\n\nmodel Resource {\n  id           String    @id\n  identityId   String    @map(\"identity_id\")\n  repositoryId String    @map(\"repository_id\")\n  folderId     String?   @map(\"folder_id\")\n  name         String\n  type         String // markdown | image | video | audio | pdf | link | code | other\n  path         String\n  size         Int       @default(0)\n  content      String?   @db.Text\n  metadata     Json      @default(\"{}\") // ResourceMetadata\n  stats        Json      @default(\"{}\") // ResourceStats\n  description  String?\n  author       String?\n  version      String?\n  tags         String    @default(\"[]\") // JSON array\n  category     String?\n  status       String    @default(\"ACTIVE\") // ACTIVE | ARCHIVED | DELETED | DRAFT\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  modifiedAt   DateTime? @map(\"modified_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  identity   Account    @relation(\"AccountResources\", fields: [identityId], references: [id])\n  repository Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([repositoryId])\n  @@index([folderId])\n  @@index([type])\n  @@index([status])\n  @@index([category])\n  @@index([createdAt])\n  @@map(\"resources\")\n}\n\nmodel RepositoryResource {\n  id           String    @id\n  identityId   String    @map(\"identity_id\")\n  repositoryId String    @map(\"repository_id\")\n  name         String\n  type         String\n  path         String\n  size         Int?\n  description  String?\n  author       String?\n  version      String?\n  tags         String?\n  category     String?\n  status       String    @default(\"active\")\n  metadata     String?\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  modifiedAt   DateTime? @map(\"modified_at\")\n\n  linkedContents LinkedContent[]\n  identity       Account             @relation(\"AccountRepositoryResources\", fields: [identityId], references: [id])\n  repository     Repository          @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n  sourceRefs     ResourceReference[] @relation(\"SourceResourceRefs\")\n  targetRefs     ResourceReference[] @relation(\"TargetResourceRefs\")\n\n  @@unique([repositoryId, path])\n  @@index([identityId])\n  @@index([type])\n  @@map(\"repository_resources\")\n}\n\nmodel LinkedContent {\n  id            String    @id\n  resourceId    String    @map(\"resource_id\")\n  title         String\n  url           String\n  contentType   String    @map(\"content_type\")\n  description   String?\n  thumbnail     String?\n  author        String?\n  publishedAt   DateTime? @map(\"published_at\")\n  isAccessible  Boolean   @default(true) @map(\"is_accessible\")\n  lastCheckedAt DateTime? @map(\"last_checked_at\")\n  cachedAt      DateTime? @map(\"cached_at\")\n  createdAt     DateTime  @default(now()) @map(\"created_at\")\n  updatedAt     DateTime  @updatedAt @map(\"updated_at\")\n\n  repositoryResource RepositoryResource @relation(fields: [resourceId], references: [id], onDelete: Cascade)\n\n  @@index([url])\n  @@map(\"linked_contents\")\n}\n\nmodel ResourceReference {\n  id               String    @id\n  sourceResourceId String    @map(\"source_resource_id\")\n  targetResourceId String    @map(\"target_resource_id\")\n  referenceType    String    @map(\"reference_type\")\n  description      String?\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n  lastVerifiedAt   DateTime? @map(\"last_verified_at\")\n\n  sourceResource RepositoryResource @relation(\"SourceResourceRefs\", fields: [sourceResourceId], references: [id], onDelete: Cascade)\n  targetResource RepositoryResource @relation(\"TargetResourceRefs\", fields: [targetResourceId], references: [id], onDelete: Cascade)\n\n  @@unique([sourceResourceId, targetResourceId, referenceType])\n  @@index([targetResourceId])\n  @@map(\"resource_references\")\n}\n\nmodel RepositoryExplorer {\n  id           String    @id\n  repositoryId String    @map(\"repository_id\")\n  identityId   String    @map(\"identity_id\")\n  name         String\n  description  String?\n  currentPath  String    @map(\"current_path\")\n  filters      String?\n  viewConfig   String?   @map(\"view_config\")\n  pinnedPaths  String?   @map(\"pinned_paths\")\n  recentPaths  String?   @map(\"recent_paths\")\n  lastScanAt   DateTime? @map(\"last_scan_at\")\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n\n  account    Account    @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  repository Repository @relation(fields: [repositoryId], references: [id], onDelete: Cascade)\n\n  @@unique([repositoryId, identityId])\n  @@index([repositoryId])\n  @@map(\"repository_explorers\")\n}\n\nmodel RepositoryStatistic {\n  id                   Int      @id @default(autoincrement())\n  identityId           String   @unique @map(\"identity_id\")\n  totalRepositories    Int      @default(0) @map(\"total_repositories\")\n  activeRepositories   Int      @default(0) @map(\"active_repositories\")\n  archivedRepositories Int      @default(0) @map(\"archived_repositories\")\n  totalResources       Int      @default(0) @map(\"total_resources\")\n  totalFiles           Int      @default(0) @map(\"total_files\")\n  totalFolders         Int      @default(0) @map(\"total_folders\")\n  gitEnabledRepos      Int      @default(0) @map(\"git_enabled_repos\")\n  totalCommits         Int      @default(0) @map(\"total_commits\")\n  totalReferences      Int      @default(0) @map(\"total_references\")\n  totalLinkedContents  Int      @default(0) @map(\"total_linked_contents\")\n  totalSizeBytes       BigInt   @default(0) @map(\"total_size_bytes\")\n  lastUpdatedAt        DateTime @default(now()) @map(\"last_updated_at\")\n  createdAt            DateTime @default(now()) @map(\"created_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@map(\"repository_statistics\")\n}\n\n/// Short-lived, identity-bound GitHub App installation orchestration intent.\n/// Only a SHA-256 hash of the provider state is persisted; no raw state or token is stored.\nmodel KnowledgeRepositoryInstallationIntent {\n  id                 String    @id\n  identityId         String    @map(\"identity_id\")\n  stateHash          String    @unique @map(\"state_hash\")\n  routeKey           String    @map(\"route_key\")\n  clientKind         String    @map(\"client_kind\")\n  returnPath         String    @map(\"return_path\")\n  status             String    @default(\"Pending\")\n  installationId     String?   @map(\"installation_id\")\n  providerAccountId  String?   @map(\"provider_account_id\")\n  setupAction        String?   @map(\"setup_action\")\n  expiresAt          DateTime  @map(\"expires_at\")\n  callbackReceivedAt DateTime? @map(\"callback_received_at\")\n  finalizedAt        DateTime? @map(\"finalized_at\")\n  consumedAt         DateTime? @map(\"consumed_at\")\n  createdAt          DateTime  @default(now()) @map(\"created_at\")\n  updatedAt          DateTime  @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId, status])\n  @@index([installationId, status])\n  @@index([expiresAt])\n  @@map(\"knowledge_repository_installation_intents\")\n}\n\n/// Stable logical knowledge space shared by local/remote bindings.\nmodel KnowledgeSpace {\n  id        String   @id\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  remoteBindings     KnowledgeRemoteBinding[]\n  documentIdentities KnowledgeDocumentIdentity[]\n\n  @@map(\"knowledge_spaces\")\n}\n\n/// ADR-090 durable identity registry. `id` is a technical row key; the product key is\n/// `(knowledgeSpaceId, knowledgeDocumentId)` and the external identity is carried by Markdown.\nmodel KnowledgeDocumentIdentity {\n  id                  String   @id @default(uuid())\n  knowledgeSpaceId    String   @map(\"knowledge_space_id\")\n  knowledgeDocumentId String   @map(\"knowledge_document_id\")\n  origin              String\n  originRequestId     String?  @map(\"origin_request_id\")\n  createdAt           DateTime @default(now()) @map(\"created_at\")\n  updatedAt           DateTime @updatedAt @map(\"updated_at\")\n\n  knowledgeSpace KnowledgeSpace @relation(fields: [knowledgeSpaceId], references: [id], onDelete: Cascade)\n\n  @@unique([knowledgeSpaceId, knowledgeDocumentId])\n  @@index([knowledgeSpaceId])\n  @@map(\"knowledge_document_identities\")\n}\n\n/// ADR-089 durable user choice: one GitHub repository is bound to a KnowledgeSpace.\n/// Provider health, sync history safety and projection state live in separate models.\nmodel KnowledgeRemoteBinding {\n  id                         String    @id\n  knowledgeSpaceId           String    @map(\"knowledge_space_id\")\n  identityId                 String    @map(\"identity_id\")\n  provider                   String    @default(\"GitHub\")\n  installationId             String    @map(\"installation_id\")\n  repositoryId               String    @map(\"repository_id\")\n  repositoryFullNameSnapshot String    @map(\"repository_full_name_snapshot\")\n  connectedAt                DateTime  @map(\"connected_at\")\n  disconnectedAt             DateTime? @map(\"disconnected_at\")\n  version                    Int       @default(1)\n\n  knowledgeSpace          KnowledgeSpace                    @relation(fields: [knowledgeSpaceId], references: [id], onDelete: Cascade)\n  account                 Account                           @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  observation             RemoteRepositoryObservation?\n  historyFence            RemoteHistoryFence?\n  projectionCheckpoint    KnowledgeProjectionCheckpoint?\n  webhookDeliveries       GithubWebhookDelivery[]\n  noteProjections         KnowledgeNoteProjection[]\n  attachmentProjections   KnowledgeAttachmentProjection[]\n  attachmentContentCaches KnowledgeAttachmentContentCache[]\n  writeRequests           KnowledgeWriteRequest[]\n\n  @@unique([identityId, repositoryId])\n  @@unique([repositoryId])\n  @@index([identityId, disconnectedAt])\n  @@index([knowledgeSpaceId, disconnectedAt])\n  @@index([installationId])\n  @@map(\"knowledge_remote_bindings\")\n}\n\n/// Latest provider observation. Provider loss never disconnects the durable binding.\nmodel RemoteRepositoryObservation {\n  bindingId             String   @id @map(\"binding_id\")\n  observedAt            DateTime @map(\"observed_at\")\n  accountId             String   @map(\"account_id\")\n  repositoryFullName    String   @map(\"repository_full_name\")\n  defaultBranch         String   @map(\"default_branch\")\n  isPrivate             Boolean  @map(\"is_private\")\n  archived              Boolean\n  disabled              Boolean\n  contentsPermission    String   @map(\"contents_permission\")\n  installationSuspended Boolean  @map(\"installation_suspended\")\n  eligibilityState      String   @map(\"eligibility_state\")\n  blockReason           String?  @map(\"block_reason\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@index([eligibilityState])\n  @@map(\"remote_repository_observations\")\n}\n\n/// Remote Git history safety cursor confirmed by the Desktop Git runtime + server preflight.\nmodel RemoteHistoryFence {\n  bindingId                  String   @id @map(\"binding_id\")\n  defaultBranch              String   @map(\"default_branch\")\n  lastConfirmedRemoteHeadSha String   @map(\"last_confirmed_remote_head_sha\")\n  confirmedAt                DateTime @map(\"confirmed_at\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@map(\"remote_history_fences\")\n}\n\n/// Server projection cursor/failure axis, independent from binding/provider state.\nmodel KnowledgeProjectionCheckpoint {\n  bindingId          String    @id @map(\"binding_id\")\n  branch             String\n  projectedCommitSha String?   @map(\"projected_commit_sha\")\n  state              String\n  failureCode        String?   @map(\"failure_code\")\n  failureMessage     String?   @map(\"failure_message\")\n  lastAttemptAt      DateTime? @map(\"last_attempt_at\")\n  projectedAt        DateTime? @map(\"projected_at\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@index([state])\n  @@map(\"knowledge_projection_checkpoints\")\n}\n\n/// Deduplication and processing cursor for GitHub webhook deliveries.\nmodel GithubWebhookDelivery {\n  id           String    @id\n  bindingId    String    @map(\"binding_id\")\n  deliveryId   String    @unique @map(\"delivery_id\")\n  eventName    String    @map(\"event_name\")\n  beforeSha    String?   @map(\"before_sha\")\n  afterSha     String?   @map(\"after_sha\")\n  forced       Boolean   @default(false)\n  status       String    @default(\"RECEIVED\")\n  errorMessage String?   @map(\"error_message\")\n  receivedAt   DateTime  @default(now()) @map(\"received_at\")\n  processedAt  DateTime? @map(\"processed_at\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@index([bindingId, status])\n  @@map(\"github_webhook_deliveries\")\n}\n\n/// Rebuildable read model derived only from the connected repository default branch.\nmodel KnowledgeNoteProjection {\n  id                  String    @id\n  bindingId           String    @map(\"binding_id\")\n  knowledgeDocumentId String?   @map(\"knowledge_document_id\")\n  relativePath        String    @map(\"relative_path\")\n  commitSha           String    @map(\"commit_sha\")\n  blobSha             String    @map(\"blob_sha\")\n  contentHash         String    @map(\"content_hash\")\n  frontmatter         Json      @default(\"{}\")\n  markdownContent     String    @map(\"markdown_content\") @db.Text\n  indexStatus         String    @default(\"PENDING\") @map(\"index_status\")\n  createdAt           DateTime  @default(now()) @map(\"created_at\")\n  updatedAt           DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt           DateTime? @map(\"deleted_at\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@unique([bindingId, relativePath])\n  @@index([bindingId, commitSha])\n  @@index([knowledgeDocumentId])\n  @@index([contentHash])\n  @@index([indexStatus])\n  @@map(\"knowledge_note_projections\")\n}\n\nmodel KnowledgeAttachmentProjection {\n  id           String    @id\n  bindingId    String    @map(\"binding_id\")\n  relativePath String    @map(\"relative_path\")\n  commitSha    String    @map(\"commit_sha\")\n  blobSha      String    @map(\"blob_sha\")\n  byteSize     Int?      @map(\"byte_size\")\n  mediaType    String    @map(\"media_type\")\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n  updatedAt    DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt    DateTime? @map(\"deleted_at\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@unique([bindingId, relativePath])\n  @@index([bindingId, commitSha])\n  @@index([blobSha])\n  @@map(\"knowledge_attachment_projections\")\n}\n\n/// Short-lived shared cache for immutable GitHub attachment bytes.\nmodel KnowledgeAttachmentContentCache {\n  bindingId    String   @map(\"binding_id\")\n  blobSha      String   @map(\"blob_sha\")\n  byteSize     Int      @map(\"byte_size\")\n  contentBytes Bytes    @map(\"content_bytes\")\n  cachedAt     DateTime @default(now()) @map(\"cached_at\")\n  expiresAt    DateTime @map(\"expires_at\")\n\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@id([bindingId, blobSha])\n  @@index([expiresAt])\n  @@map(\"knowledge_attachment_content_cache\")\n}\n\n/// Idempotency ledger for confirmed Web note creation requests.\n/// The Git commit state (`status`/`commitSha`) and the projection operation\n/// state (`projectionStatus`/`projectionError*`/`projectedAt`) are tracked\n/// separately so a Committed note whose projection is pending/failed stays\n/// visible and replayable instead of being conflated with the commit result.\nmodel KnowledgeWriteRequest {\n  id                     String    @id\n  identityId             String    @map(\"identity_id\")\n  bindingId              String    @map(\"binding_id\")\n  knowledgeDocumentId    String    @map(\"knowledge_document_id\")\n  requestId              String    @map(\"request_id\")\n  requestHash            String    @map(\"request_hash\")\n  relativePath           String    @map(\"relative_path\")\n  status                 String    @default(\"PENDING\")\n  commitSha              String?   @map(\"commit_sha\")\n  errorCode              String?   @map(\"error_code\")\n  errorMessage           String?   @map(\"error_message\")\n  projectionStatus       String    @default(\"PENDING\") @map(\"projection_status\")\n  projectionErrorCode    String?   @map(\"projection_error_code\")\n  projectionErrorMessage String?   @map(\"projection_error_message\")\n  projectionAttempts     Int       @default(0) @map(\"projection_attempts\")\n  projectedAt            DateTime? @map(\"projected_at\")\n  blobSha                String?   @map(\"blob_sha\")\n  markdownContent        String?   @map(\"markdown_content\") @db.Text\n  createdAt              DateTime  @default(now()) @map(\"created_at\")\n  updatedAt              DateTime  @updatedAt @map(\"updated_at\")\n  completedAt            DateTime? @map(\"completed_at\")\n\n  account Account                @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  binding KnowledgeRemoteBinding @relation(fields: [bindingId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, requestId])\n  @@index([bindingId, status])\n  @@index([knowledgeDocumentId])\n  @@map(\"knowledge_write_requests\")\n}\n\n/// Short-lived distributed worker ownership for rebuildable repository work.\nmodel KnowledgeRepositoryLease {\n  id         String   @id\n  leaseKey   String   @unique @map(\"lease_key\")\n  ownerToken String   @map(\"owner_token\")\n  expiresAt  DateTime @map(\"expires_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([expiresAt])\n  @@map(\"knowledge_repository_leases\")\n}\n\n// ==========================================\n// Schedule Module\n// CalendarEntry product truth + canonical Temporal Engine runtime\n// ==========================================\n\nmodel Schedule {\n  id          String    @id\n  identityId  String    @map(\"identity_id\")\n  title       String\n  description String?\n  // ADR-080 canonical CalendarEntry range truth. Timed and AllDay are mutually exclusive by domain invariant.\n  rangeKind   String    @map(\"range_kind\")\n  timedStart  DateTime? @map(\"timed_start\")\n  timedEnd    DateTime? @map(\"timed_end\")\n  allDayStart String?   @map(\"all_day_start\")\n  allDayEnd   String?   @map(\"all_day_end\")\n  location    String?\n  attendees   String?\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  version     Int       @default(1)\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId, rangeKind, timedStart, timedEnd], map: \"schedules_timed_range_idx\")\n  @@index([identityId, rangeKind, allDayStart, allDayEnd], map: \"schedules_all_day_range_idx\")\n  @@map(\"schedules\")\n}\n\n/// Durable evidence for one owner-level desired-state reconcile.\n/// Successful rows are written inside the same transaction as ScheduledInvocation reconcile.\n\nmodel ScheduledInvocation {\n  id                String    @id\n  identityId        String    @map(\"identity_id\")\n  ownerType         String    @map(\"owner_type\")\n  ownerId           String    @map(\"owner_id\")\n  schedulingKey     String    @map(\"scheduling_key\")\n  handlerKey        String    @map(\"handler_key\")\n  payloadVersion    Int       @map(\"payload_version\")\n  payload           Json\n  runAt             DateTime  @map(\"run_at\")\n  sourceRevision    Json?     @map(\"source_revision\")\n  retryEnabled      Boolean   @default(true) @map(\"retry_enabled\")\n  maxRetries        Int       @map(\"max_retries\")\n  initialDelayMs    Int       @map(\"initial_delay_ms\")\n  maxDelayMs        Int       @map(\"max_delay_ms\")\n  backoffMultiplier Float     @map(\"backoff_multiplier\")\n  priority          String\n  timeoutMs         Int?      @map(\"timeout_ms\")\n  status            String\n  attemptCount      Int       @default(0) @map(\"attempt_count\")\n  nextAttemptAt     DateTime? @map(\"next_attempt_at\")\n  claimToken        String?   @map(\"claim_token\")\n  claimExpiresAt    DateTime? @map(\"claim_expires_at\")\n  fencingToken      Int       @default(0) @map(\"fencing_token\")\n  name              String?\n  tags              Json\n  createdAt         DateTime  @default(now()) @map(\"created_at\")\n  updatedAt         DateTime  @updatedAt @map(\"updated_at\")\n\n  account  Account             @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  attempts InvocationAttempt[]\n\n  @@unique([identityId, ownerType, ownerId, schedulingKey], map: \"scheduled_invocations_owner_key_unique\")\n  @@index([identityId, status, nextAttemptAt], map: \"scheduled_invocations_due_idx\")\n  @@index([identityId, ownerType, ownerId], map: \"scheduled_invocations_owner_idx\")\n  @@map(\"scheduled_invocations\")\n}\n\nmodel InvocationAttempt {\n  id               String    @id\n  identityId       String    @map(\"identity_id\")\n  invocationId     String    @map(\"invocation_id\")\n  attemptNumber    Int       @map(\"attempt_number\")\n  startedAt        DateTime  @map(\"started_at\")\n  finishedAt       DateTime? @map(\"finished_at\")\n  outcome          String\n  result           Json?\n  failureCode      String?   @map(\"failure_code\")\n  failureMessage   String?   @map(\"failure_message\")\n  failureRetryable Boolean?  @map(\"failure_retryable\")\n  workerId         String?   @map(\"worker_id\")\n  claimToken       String?   @map(\"claim_token\")\n  fencingToken     Int?      @map(\"fencing_token\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n\n  account    Account             @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  invocation ScheduledInvocation @relation(fields: [invocationId], references: [id], onDelete: Cascade)\n\n  @@unique([invocationId, attemptNumber], map: \"invocation_attempts_number_unique\")\n  @@index([identityId, invocationId, createdAt], map: \"invocation_attempts_lookup_idx\")\n  @@map(\"invocation_attempts\")\n}\n\nmodel SchedulingReconcileOperation {\n  operationId      String   @id @map(\"operation_id\")\n  identityId       String   @map(\"identity_id\")\n  ownerType        String   @map(\"owner_type\")\n  ownerId          String   @map(\"owner_id\")\n  status           String\n  desiredCount     Int      @map(\"desired_count\")\n  createdCount     Int      @map(\"created_count\")\n  updatedCount     Int      @map(\"updated_count\")\n  deletedCount     Int      @map(\"deleted_count\")\n  unchangedCount   Int      @map(\"unchanged_count\")\n  failureCode      String?  @map(\"failure_code\")\n  failureMessage   String?  @map(\"failure_message\")\n  failureRetryable Boolean? @map(\"failure_retryable\")\n  startedAt        DateTime @map(\"started_at\")\n  finishedAt       DateTime @map(\"finished_at\")\n  createdAt        DateTime @default(now()) @map(\"created_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@index([identityId, ownerType, ownerId, finishedAt], map: \"scheduling_reconcile_owner_history_idx\")\n  @@map(\"scheduling_reconcile_operations\")\n}\n\n/// R3a：调度器宿主互斥租约（DB lease/heartbeat）。\n/// 共享数据库的多个宿主（API 多实例、同库进程）通过本表互斥：\n/// 只有成功 acquire 的宿主启动 ScheduledInvocationQueue；其余宿主只消费读模型。\nmodel ScheduleLease {\n  id         String   @id\n  leaseKey   String   @unique @map(\"lease_key\")\n  ownerToken String   @map(\"owner_token\")\n  expiresAt  DateTime @map(\"expires_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  @@index([expiresAt])\n  @@map(\"schedule_leases\")\n}\n\nmodel ScheduleRebuildOutbox {\n  id             String    @id @default(uuid())\n  identityId     String    @map(\"identity_id\")\n  scheduleId     String?   @map(\"schedule_id\")\n  startTime      DateTime  @map(\"start_time\")\n  endTime        DateTime  @map(\"end_time\")\n  sourceRevision Int       @default(1) @map(\"source_revision\")\n  idempotencyKey String?   @unique @map(\"idempotency_key\")\n  status         String    @default(\"pending\")\n  attempts       Int       @default(0)\n  claimToken     String?   @map(\"claim_token\")\n  claimedAt      DateTime? @map(\"claimed_at\")\n  nextAttemptAt  DateTime? @map(\"next_attempt_at\")\n  lastError      String?   @map(\"last_error\")\n  processedAt    DateTime? @map(\"processed_at\")\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n\n  @@index([identityId, status])\n  @@map(\"schedule_rebuild_outbox\")\n}\n\nmodel ScheduleDomainEventOutbox {\n  id             String    @id @default(uuid())\n  identityId     String    @map(\"identity_id\")\n  scheduleId     String    @map(\"schedule_id\")\n  eventType      String    @map(\"event_type\")\n  payload        String\n  status         String    @default(\"pending\")\n  attempts       Int       @default(0)\n  claimToken     String?   @map(\"claim_token\")\n  claimedAt      DateTime? @map(\"claimed_at\")\n  nextAttemptAt  DateTime? @map(\"next_attempt_at\")\n  publishedAt    DateTime? @map(\"published_at\")\n  lastError      String?   @map(\"last_error\")\n  idempotencyKey String    @unique @map(\"idempotency_key\")\n  createdAt      DateTime  @default(now()) @map(\"created_at\")\n  updatedAt      DateTime  @updatedAt @map(\"updated_at\")\n\n  @@index([identityId, status])\n  @@map(\"schedule_domain_event_outbox\")\n}\n\n/// Durable consumer receipt for at-least-once domain-event delivery.\n/// Consumers with side effects must record a receipt keyed by the envelope's\n/// idempotencyKey inside their own durable transaction; the unique constraint\n/// makes the dedup atomic under concurrency.\nmodel ScheduleEventConsumerReceipt {\n  id             String   @id @default(uuid())\n  idempotencyKey String   @unique @map(\"idempotency_key\")\n  effectCount    Int      @default(0) @map(\"effect_count\")\n  consumedAt     DateTime @default(now()) @map(\"consumed_at\")\n\n  @@map(\"schedule_event_consumer_receipt\")\n}\n\n/// Independent durable business side effect written by the schedule\n/// delivery-log consumer (P1-1). The consumer commits the receipt\n/// (ScheduleEventConsumerReceipt) and exactly one delivery-log row in the same\n/// transaction; both carry their own unique idempotency_key so concurrent\n/// duplicate delivery converges to exactly one of each.\nmodel ScheduleEventDeliveryLog {\n  id             String   @id @default(uuid())\n  idempotencyKey String   @unique @map(\"idempotency_key\")\n  eventType      String   @map(\"event_type\")\n  aggregateId    String?  @map(\"aggregate_id\")\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n\n  @@index([aggregateId])\n  @@map(\"schedule_event_delivery_log\")\n}\n\n// ==========================================\n// Setting Module\n// Canonical user preferences: namespace-scoped persistence\n// ==========================================\n\n// Canonical Setting vNext preferences. Namespace rows are the sync/CAS unit.\nmodel UserPreferenceRecord {\n  id         String   @id @default(uuid())\n  identityId String   @map(\"identity_id\")\n  namespace  String\n  payload    Json\n  revision   Int      @default(1)\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  @@unique([identityId, namespace])\n  @@index([identityId])\n  @@map(\"user_preference_records\")\n}\n\n// ==========================================\n// Task Module\n// 任务计划、实例、历史、统计\n// ==========================================\n\n/// TaskPlan 聚合根 - 任务模板\n/// 管理任务的完整定义，包括时间配置、重复规则、提醒、Goal绑定等\nmodel TaskPlan {\n  // ============ 主键与外键 ============\n  id         String @id\n  identityId String @map(\"identity_id\")\n\n  // ============ 基础信息 ============\n  name             String\n  description      String?\n  status           String /// Task lifecycle: Active | Paused | Closed\n  outcome          String    @default(\"Open\") /// Open | Succeeded | Failed | Abandoned\n  completionPolicy String    @default(\"AllowCorrection\") @map(\"completion_policy\")\n  closedAt         DateTime? @map(\"closed_at\")\n  archivedAt       DateTime? @map(\"archived_at\")\n  abandonedReason  String?   @map(\"abandoned_reason\")\n  importance       String    @default(\"moderate\") /// ImportanceLevel\n\n  // ============ Canonical scheduling/reminder truth ============\n  schedule       Json /// TaskPlanSchedule canonical JSON\n  reminderConfig String? @map(\"reminder_config\") /// JSON: TaskReminderConfig\n\n  // ============ Goal 绑定（展开的关系值对象） ============\n  goalId              String? @map(\"goal_id\")\n  keyResultId         String? @map(\"key_result_id\")\n  goalRecordValue     Float?  @map(\"goal_record_value\")\n  goalProgressTrigger String? @map(\"goal_progress_trigger\")\n\n  // ============ 检查列表（JSON值对象） ============\n  checklist String? @map(\"checklist\") /// JSON: ChecklistItemDefinition[]\n\n  // ============ 版本与审计 ============\n  version   Int       @default(1)\n  createdAt DateTime  @default(now()) @map(\"created_at\")\n  updatedAt DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt DateTime? @map(\"deleted_at\")\n\n  // ============ 关系映射 ============\n  account   Account    @relation(fields: [identityId], references: [id], onDelete: Cascade)\n  keyResult KeyResult? @relation(\"KeyResultTaskPlans\", fields: [keyResultId, goalId, identityId], references: [id, goalId, identityId], onDelete: Restrict)\n\n  // 实例\n  occurrences TaskOccurrence[]\n  history     TaskPlanHistory[]\n  labelLinks  TaskLabel[]\n\n  // ============ 索引优化 ============\n  @@unique([id, identityId])\n  @@index([identityId])\n  @@index([status])\n  @@index([importance])\n  @@index([identityId, goalId, deletedAt])\n  @@index([identityId, keyResultId, deletedAt])\n  @@index([deletedAt])\n  @@map(\"task_plans\")\n}\n\n/// TaskOccurrence 聚合根 - 任务实例\n/// 从模板生成的具体任务实例，包含执行状态和时间追踪\nmodel TaskOccurrence {\n  id                 String    @id\n  planId             String    @map(\"plan_id\")\n  identityId         String    @map(\"identity_id\")\n  occurrenceKey      String    @map(\"occurrence_key\")\n  scheduleDate       String    @map(\"schedule_date\") /// Ymd (YYYY-MM-DD)\n  scheduleTiming     String    @map(\"schedule_timing\") /// JSON: TaskTiming\n  importanceSnapshot String    @default(\"Moderate\") @map(\"importance_snapshot\")\n  status             String /// TaskOccurrenceStatus\n  actualStartAt      DateTime? @map(\"actual_start_at\")\n  result             String? /// JSON: TaskOccurrenceResult\n  checklistState     String    @default(\"[]\") @map(\"checklist_state\") /// JSON: TaskOccurrenceChecklistItem[]\n  version            Int       @default(1)\n  createdAt          DateTime  @default(now()) @map(\"created_at\")\n  updatedAt          DateTime  @updatedAt @map(\"updated_at\")\n  deletedAt          DateTime? @map(\"deleted_at\")\n\n  account Account  @relation(fields: [identityId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  plan    TaskPlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@unique([planId, occurrenceKey])\n  @@index([planId, scheduleDate])\n  @@index([identityId, status])\n  @@index([identityId, scheduleDate])\n  @@map(\"task_occurrences\")\n}\n\n/// Durable delivery log for completed tasks that contribute Goal progress.\n/// It is intentionally task-specific rather than a generic application outbox.\nmodel TaskGoalOutbox {\n  eventId          String    @id @map(\"event_id\")\n  identityId       String    @map(\"identity_id\")\n  taskOccurrenceId String    @map(\"task_occurrence_id\")\n  taskPlanId       String    @map(\"task_plan_id\")\n  goalId           String    @map(\"goal_id\")\n  keyResultId      String    @map(\"key_result_id\")\n  payload          String\n  action           String    @default(\"complete\")\n  status           String    @default(\"PENDING\")\n  attempts         Int       @default(0)\n  availableAt      DateTime  @default(now()) @map(\"available_at\")\n  lastError        String?   @map(\"last_error\")\n  dispatchedAt     DateTime? @map(\"dispatched_at\")\n  createdAt        DateTime  @default(now()) @map(\"created_at\")\n  updatedAt        DateTime  @updatedAt @map(\"updated_at\")\n\n  @@index([identityId, status, availableAt])\n  @@index([status, availableAt])\n  @@index([taskOccurrenceId])\n  @@map(\"task_goal_outbox\")\n}\n\nmodel TaskPlanHistory {\n  id         String   @id\n  identityId String   @map(\"identity_id\")\n  planId     String   @map(\"plan_id\")\n  action     String\n  changes    String?\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  identity Account  @relation(\"AccountTaskPlanHistory\", fields: [identityId], references: [id])\n  plan     TaskPlan @relation(fields: [planId], references: [id], onDelete: Cascade)\n\n  @@index([identityId])\n  @@index([planId])\n  @@map(\"task_plan_history\")\n}\n\n// ==========================================\n// Wallet (R7 试点)\n// 第一个外部模块：交易/预算/账户，与 Goal 通过 Relation 连接\n// ==========================================\n\nmodel WalletAccount {\n  id         String   @id\n  identityId String   @map(\"identity_id\")\n  name       String\n  currency   String   @default(\"CNY\")\n  balance    Decimal  @default(0)\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  account Account @relation(fields: [identityId], references: [id], onDelete: Cascade)\n\n  transactions WalletTransaction[]\n\n  @@index([identityId])\n  @@map(\"wallet_accounts\")\n}\n\nmodel WalletTransaction {\n  id         String   @id\n  accountId  String   @map(\"account_id\")\n  identityId String   @map(\"identity_id\")\n  type       String /// income | expense | transfer\n  amount     Decimal\n  category   String?\n  note       String?\n  goalId     String?  @map(\"goal_id\") /// 与 Goal 的 relation（contributes_to）\n  occurredAt DateTime @map(\"occurred_at\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  account          WalletAccount @relation(fields: [accountId], references: [id], onDelete: Cascade)\n  account_identity Account       @relation(\"AccountWalletTransactions\", fields: [identityId], references: [id])\n\n  @@index([identityId, occurredAt])\n  @@map(\"wallet_transactions\")\n}\n"
}

